{
  "workflow": {
    "activities": [
      {
        "id": "A1",
        "name": "Confirm planned pickup arrangement",
        "actor": "Mother",
        "system": "Shared family calendar",
        "inputs": ["Pickup schedule", "Partner/backup caregiver availability"],
        "outputs": ["Confirmed pickup plan for the day"]
      },
      {
        "id": "A2",
        "name": "Verify collector against authorized pickup list",
        "actor": "Mother",
        "system": "Authorized pickup list held by provider",
        "inputs": ["Confirmed pickup plan", "Authorized pickup list"],
        "outputs": ["Authorization status of planned collector"]
      },
      {
        "id": "A3",
        "name": "Monitor for collector unavailability during the day",
        "actor": "Mother",
        "system": "Childcare messaging app / shared family calendar",
        "inputs": ["Confirmed pickup plan", "Collector availability updates"],
        "outputs": ["Unavailability notification if collector cannot proceed"]
      },
      {
        "id": "A4",
        "name": "Identify replacement collector",
        "actor": "Mother",
        "system": "Shared family calendar",
        "inputs": ["Unavailability notification", "Backup caregiver contact details"],
        "outputs": ["Proposed replacement collector"]
      },
      {
        "id": "A5",
        "name": "Check replacement collector against authorized pickup list",
        "actor": "Mother",
        "system": "Authorized pickup list held by provider",
        "inputs": ["Proposed replacement collector", "Authorized pickup list"],
        "outputs": ["Authorization status of replacement collector"]
      },
      {
        "id": "A6",
        "name": "Request teacher acknowledgment for new collector",
        "actor": "Mother",
        "system": "Childcare messaging app",
        "inputs": ["Proposed replacement collector", "Authorization gap identified"],
        "outputs": ["Teacher acknowledgment of new collector"]
      },
      {
        "id": "A7",
        "name": "Collector performs pickup at provider",
        "actor": "Collector (partner or backup caregiver)",
        "system": "None specified",
        "inputs": ["Teacher acknowledgment (if required)", "Confirmed pickup plan"],
        "outputs": ["Child collected from provider"]
      },
      {
        "id": "A8",
        "name": "Record home arrival in family handover log",
        "actor": "Collector",
        "system": "Family handover log",
        "inputs": ["Child collected from provider"],
        "outputs": ["Home arrival confirmation entry"]
      },
      {
        "id": "A9",
        "name": "Check handover log at end of pickup window",
        "actor": "Mother",
        "system": "Family handover log",
        "inputs": ["Pickup window end time", "Family handover log"],
        "outputs": ["Confirmation status: logged or missing"]
      },
      {
        "id": "A10",
        "name": "Follow up with collector and teacher if confirmation missing",
        "actor": "Mother",
        "system": "Childcare messaging app / direct contact",
        "inputs": ["Missing confirmation status", "Collector contact details", "Teacher contact details"],
        "outputs": ["Resolution of missing confirmation or escalation"]
      }
    ],
    "decisions": [
      {
        "id": "D1",
        "condition": "Is the planned collector still available on the day?",
        "branches": [
          "Yes — proceed with original pickup plan (go to A7)",
          "No — identify replacement collector (go to A4)"
        ]
      },
      {
        "id": "D2",
        "condition": "Is the replacement collector already on the authorized pickup list?",
        "branches": [
          "Yes — replacement may proceed to collect (go to A7)",
          "No — request teacher acknowledgment before collection (go to A6)"
        ]
      },
      {
        "id": "D3",
        "condition": "Has home arrival been logged in the handover log by end of pickup window?",
        "branches": [
          "Yes — process complete",
          "No — follow up with collector and teacher (go to A10)"
        ]
      }
    ],
    "exceptions": [
      {
        "id": "E1",
        "description": "Planned collector becomes unavailable during the day",
        "trigger": "Collector confirms unavailability",
        "handling": "Mother identifies replacement, checks authorization, requests teacher acknowledgment if needed (A4 → A5 → D2)"
      },
      {
        "id": "E2",
        "description": "Collection confirmation not logged by end of pickup window",
        "trigger": "Handover log entry absent at pickup window close",
        "handling": "Mother contacts both collector and teacher directly (A10)"
      },
      {
        "id": "E3",
        "description": "Replacement collector not on authorized pickup list",
        "trigger": "Authorization check at D2 fails",
        "handling": "Mother sends formal acknowledgment request to teacher via messaging app before collection proceeds (A6)"
      }
    ],
    "dependencies": [
      {"from": "A1", "to": "A2", "type": "control_flow"},
      {"from": "A2", "to": "A3", "type": "control_flow"},
      {"from": "A3", "to": "D1", "type": "control_flow"},
      {"from": "D1", "to": "A7", "type": "control_flow"},
      {"from": "D1", "to": "A4", "type": "control_flow"},
      {"from": "A4", "to": "A5", "type": "control_flow"},
      {"from": "A5", "to": "D2", "type": "control_flow"},
      {"from": "D2", "to": "A7", "type": "control_flow"},
      {"from": "D2", "to": "A6", "type": "control_flow"},
      {"from": "A6", "to": "A7", "type": "control_flow"},
      {"from": "A7", "to": "A8", "type": "control_flow"},
      {"from": "A8", "to": "A9", "type": "control_flow"},
      {"from": "A9", "to": "D3", "type": "control_flow"},
      {"from": "D3", "to": "A10", "type": "control_flow"}
    ]
  },
  "automation_opportunities": [
    {
      "target": "A1 — Confirm planned pickup arrangement",
      "rationale": "A shared family calendar already exists; an automated daily reminder or status-check notification could prompt the collector to confirm availability without manual mother intervention, reducing the five-minute daily coordination effort.",
      "required_data": ["Collector identity for the day", "Pickup time", "Calendar integration access"],
      "constraints": ["Collector must actively respond to confirmation prompt", "Notification timing must precede the latest point at which a change can be actioned"],
      "confidence": "high"
    },
    {
      "target": "A2 / A5 — Verify collector against authorized pickup list",
      "rationale": "Authorization checks are rule-based lookups against a maintained list. This could be automated so that when a collector name is entered or changed, the system instantly returns authorization status without manual cross-referencing.",
      "required_data": ["Current authorized pickup list", "Collector identity"],
      "constraints": ["Authorized pickup list must be maintained in a queryable digital format", "List update process (adding new collectors) must remain human-controlled"],
      "confidence": "medium"
    },
    {
      "target": "A6 — Request teacher acknowledgment for new collector",
      "rationale": "The childcare messaging app is already used for this communication. A structured in-app request template could automate message composition and track acknowledgment status, reducing manual drafting and follow-up.",
      "required_data": ["New collector name", "Reason for change", "Teacher contact in messaging app"],
      "constraints": ["Teacher acknowledgment must remain a human decision", "Messaging app must support structured request types or templates"],
      "confidence": "medium"
    },
    {
      "target": "A9 — Check handover log at end of pickup window",
      "rationale": "Monitoring the handover log for a missing entry by a deadline is a straightforward time-triggered check that can be fully automated, generating an alert to the mother rather than requiring her to remember to check.",
      "required_data": ["Pickup window end time", "Handover log entry status", "Mother notification contact"],
      "constraints": ["Handover log must be a digital system accessible for automated querying", "Pickup window end time must be defined and consistent or configurable per day"],
      "confidence": "high"
    },
    {
      "target": "D3 / A10 — Trigger follow-up when confirmation is missing",
      "rationale": "If the handover log check is automated (see A9), the follow-up alert to the mother can also be automatically dispatched, and a pre-composed message to the collector and teacher could be generated, reducing response lag in a safety-critical exception.",
      "required_data": ["Collector contact details", "Teacher contact details", "Handover log status", "Pickup window end time"],
      "constraints": ["Final outreach decision and escalation judgment should remain with the mother", "Contact details must be current and stored securely"],
      "confidence": "medium"
    }
  ],
  "remaining_gaps": [
    {
      "id": "G1",
      "description": "The exact format and platform of the family handover log are not specified — it is unclear whether it is a digital app, a shared document, or a manual record, which affects automation feasibility for A8 and A9."
    },
    {
      "id": "G2",
      "description": "The defined pickup window end time is not specified — it is unknown whether this is a fixed daily time or varies, which is needed to configure automated log-check triggers."
    },
    {
      "id": "G3",
      "description": "The process for formally adding a new person to the authorized pickup list is not fully described — it is unclear who initiates it, what documentation is required, and how long it takes."
    },
    {
      "id": "G4",
      "description": "The additional time required to handle a collector change is acknowledged but not quantified, making it difficult to assess the full process duration in exception scenarios."
    },
    {
      "id": "G5",
      "description": "It is not specified whether the childcare messaging app supports structured or templated messages, which affects the feasibility of automating A6."
    },
    {
      "id": "G6",
      "description": "The escalation path beyond A10 (if the collector and teacher cannot be reached or the child's whereabouts remain unconfirmed) is not described."
    },
    {
      "id": "G7",
      "description": "It is unclear whether the backup caregiver is always pre-listed on the authorized pickup list or whether teacher acknowledgment is routinely required for them."
    }
  ]
}
